args.sql:
SELECT DISTINCT (c.scoredate - (c.tenureyrs || ' years')::interval)::date AS start_date,
  EXTRACT(QUARTER FROM (c.scoredate - (c.tenureyrs || ' years')::interval))::int AS q
FROM core_record c ORDER BY start_date LIMIT 20;

